INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷83·晋少帝本纪·开运二年四月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/74486f99392b820f87f1b0c58501ef7c8c04d896/content/books/zizhi-tongjian/vol-284/year-0945/part-03/sources/library/jiuwudaishi-083-945-april/source.txt", "note": "《旧五代史》卷83·晋少帝本纪·开运二年四月，段落 jiu-wudaishi-205deb4a7860-p002022；上下文、卷界及传主已校核，纸本及异文待核。", "id": "6883a3fb-f609-54b6-84b6-fa709e08af22"}, {"title": "旧五代史·卷83·晋少帝本纪·开运二年三月战事续段", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/74486f99392b820f87f1b0c58501ef7c8c04d896/content/books/zizhi-tongjian/vol-284/year-0945/part-03/sources/library/jiuwudaishi-083-945-march-continuation/source.txt", "note": "《旧五代史》卷83·晋少帝本纪·开运二年三月战事续段，段落 jiu-wudaishi-205deb4a7860-p002021；上下文、卷界及传主已校核，纸本及异文待核。", "id": "c79df82b-f3ea-5b13-a7a3-fff0dd3cdd68"}, {"title": "宋史·卷251·符彦卿传·阳城之战", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/74486f99392b820f87f1b0c58501ef7c8c04d896/content/books/zizhi-tongjian/vol-284/year-0945/part-03/sources/library/songshi-251-fu-yangcheng/source.txt", "note": "《宋史》卷251·符彦卿传·阳城之战，段落 songshi-9c6e46fee832-p057287；上下文、卷界及传主已校核，纸本及异文待核。", "id": "4429b292-e993-54f9-a276-12bd05efdede"}, {"title": "宋史·卷254·药元福传·籍贯及早年", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/74486f99392b820f87f1b0c58501ef7c8c04d896/content/books/zizhi-tongjian/vol-284/year-0945/part-03/sources/library/songshi-254-yao-origins/source.txt", "note": "《宋史》卷254·药元福传·籍贯及早年，段落 songshi-9c6e46fee832-p057505；上下文、卷界及传主已校核，纸本及异文待核。", "id": "92b6141e-2b7b-5607-9011-16caba69688f"}, {"title": "宋史·卷254·药元福传·阳城之战", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/74486f99392b820f87f1b0c58501ef7c8c04d896/content/books/zizhi-tongjian/vol-284/year-0945/part-03/sources/library/songshi-254-yao-yangcheng/source.txt", "note": "《宋史》卷254·药元福传·阳城之战，段落 songshi-9c6e46fee832-p057507；上下文、卷界及传主已校核，纸本及异文待核。", "id": "658fca06-fd7f-51e0-af84-a04bd757c7e7"}, {"title": "资治通鉴·卷284·开运二年三月至四月（末段福州事在本批处理）", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/74486f99392b820f87f1b0c58501ef7c8c04d896/content/books/zizhi-tongjian/vol-284/year-0945/part-03/sources/library/tongjian-284-945-yangcheng-april/source.txt", "note": "《资治通鉴》卷284·开运二年三月至四月（末段福州事在本批处理），段落 zizhi-tongjian-a63549944a71-p003380；上下文、卷界及传主已校核，纸本及异文待核。", "id": "b0048b6b-a749-5e6c-936a-4f829f6a8441"}, {"title": "新五代史·卷52·张彦泽传·阳城之战", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/74486f99392b820f87f1b0c58501ef7c8c04d896/content/books/zizhi-tongjian/vol-284/year-0945/part-03/sources/library/xinwudaishi-052-zhang-yangcheng/source.txt", "note": "《新五代史》卷52·张彦泽传·阳城之战，段落 xin-wudaishi-b08f244b9241-p002051；上下文、卷界及传主已校核，纸本及异文待核。", "id": "41ef6e6b-b4f8-512b-91ed-b2a174d2bf6d"}, {"title": "新五代史·卷68·闽世家·王继昌及卓俨明（后文未在本批提前处理）", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/74486f99392b820f87f1b0c58501ef7c8c04d896/content/books/zizhi-tongjian/vol-284/year-0945/part-03/sources/library/xinwudaishi-068-li-ren-da/source.txt", "note": "《新五代史》卷68·闽世家·王继昌及卓俨明（后文未在本批提前处理），段落 xin-wudaishi-b08f244b9241-p003414；上下文、卷界及传主已校核，纸本及异文待核。", "id": "4c007e7d-1965-54c8-99ae-fa57eab6e1a4"}, {"title": "资治通鉴·卷284·开运二年二月至三月（后续福州政变与北征留后续）", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7ec152ca6b93afb639ad0febcd3c8be43a631b52/content/books/zizhi-tongjian/vol-284/year-0945/part-02/sources/library/tongjian-284-945-february-march/source.txt", "note": "《资治通鉴》卷284·开运二年二月至三月（后续福州政变与北征留后续），段落 zizhi-tongjian-a63549944a71-p003379；上下文、卷年与传主已校核，纸本及异文待核。", "id": "6c12b2ff-62fc-5257-9c04-68d33dba15eb"}, {"title": "旧五代史·卷83·晋少帝本纪·开运二年三月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7ec152ca6b93afb639ad0febcd3c8be43a631b52/content/books/zizhi-tongjian/vol-284/year-0945/part-02/sources/library/jiuwudaishi-083-945-march/source.txt", "note": "《旧五代史》卷83·晋少帝本纪·开运二年三月，段落 jiu-wudaishi-205deb4a7860-p002020；上下文、卷年与传主已校核，纸本及异文待核。", "id": "fe241d3b-a2e9-5a28-ab85-e8715cedb7a1"}, {"title": "新五代史·卷9·晋本纪第九·出帝开运二年", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ac10110d193f69ce3499423e4fa4db294584e2ff/content/books/zizhi-tongjian/vol-284/year-0945/part-01/sources/library/xinwudaishi-009-945/source.txt", "note": "《新五代史》卷9·晋本纪第九·出帝开运二年，段落 xin-wudaishi-b08f244b9241-p000336；已核上下文及传主，纸本及异文待核。", "id": "e3160060-6159-5733-9a3f-cd13016527db"}, {"title": "辽史·卷4·太宗本纪·会同八年三月", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7ec152ca6b93afb639ad0febcd3c8be43a631b52/content/books/zizhi-tongjian/vol-284/year-0945/part-02/sources/library/liaoshi-004-945-march/source.txt", "note": "《辽史》卷4·太宗本纪·会同八年三月，段落 liaoshi-7cd182a20e67-p000557；上下文、卷年与传主已校核，纸本及异文待核。", "id": "23623d25-c3e3-52e4-917e-04a37b41c2f7"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "李仁达", "aliases": ["李仁達"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "光州人，曾任闽元从指挥使，多次在建州、福州之间投奔不同执政者。945年与陈继珣、黄仁讽发动福州政变，杀王继昌和吴成义，拥立僧卓岩明。后来又杀黄仁讽、陈继珣，将福州兵权集中到自己手中。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "97ca7dea-54b1-5a38-a747-3dc803037d55"}, {"name": "王延政", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王延政，都教练使、赴建州抚慰者。", "biography": null, "status": "draft", "id": "83601670-f3dc-5559-b599-e39bda91eb6c"}, {"name": "朱文进", "aliases": ["硃文进", "朱文進", "硃文進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "永泰人，闽国拱宸军将领。《资治通鉴》记他与连重遇多次受王继鹏侮辱而心怀不满，《新五代史》还记二人因宸卫军待遇优厚而激怒部众。生卒年未载。", "biography": null, "status": "draft", "id": "309ef83c-46fe-51a1-86cc-c2cb8dc48d82"}, {"name": "陈继珣", "aliases": ["陳繼珣"], "era": "五代十国", "birth_year": null, "death_year": 945, "description": "浦城人，曾离王延政投奔王延羲，因献攻建州方案任著作郎。945年与李仁达、黄仁讽发动福州政变，后受李仁达任命驻北门，又被李仁达以谋反告发而杀。出生年未载。", "biography": null, "status": "draft", "id": "b6fe3893-9034-5fef-ba12-144f9341d697"}, {"name": "王延羲", "aliases": ["王曦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国宗室，王继鹏的叔父，曾任左仆射、同平章事。939年被政变军队拥立，自称威武节度使、闽国王，更名王曦，改元永隆。生卒年暂未核实。", "biography": null, "status": "draft", "id": "e706d6ae-56f4-5e44-9d24-f3060ae87cbb"}, {"name": "王继昌", "aliases": ["王繼昌"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "王延政的从子，任门下侍郎、同平章事。945年王延政因南唐来攻而暂不迁都，任他都督南都内外诸军事，驻福州。父亲姓名及生卒年本次引文未载。", "biography": null, "status": "draft", "id": "8f9c1ae4-de5b-55c7-a1f1-0764d9c37826"}, {"name": "黄仁讽", "aliases": ["黃仁諷"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国飞捷指挥使。945年王延政任他为镇遏使，率军作为王继昌的后援。生卒年本段未载。", "biography": null, "status": "draft", "id": "c3e8e01d-6411-59a0-8486-93d2b678ca18"}, {"name": "吴成义", "aliases": ["吳成義"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "殷国统军使。944年闽国政变后受王延政命率兵讨伐朱文进，未能攻克。后续福建战事尚随主书继续录入。生卒年未载。", "biography": null, "status": "draft", "id": "5b79c091-612f-5d81-9f36-da75ba08386b"}, {"name": "卓岩明", "aliases": ["卓巖明", "卓俨明", "卓儼明"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "雪峰寺僧，945年三月己亥被李仁达等拥立为帝，仍称天福十年并向后晋称臣。主书写卓岩明，新五代史对应同寺、同场立帝写卓俨明，作为姓名异文保留。生卒年本段未载。", "biography": null, "status": "draft", "id": "e264fb4f-ee2d-56c5-a674-02bd304ddd75"}, {"name": "张汉真", "aliases": ["張漢真"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "殷国将领。944年从镛州率八千兵将到建阳一带，查文徽获知后退回建阳。与泉州军将张汉思没有同人证据，不合并。生卒年本段未载。", "biography": null, "status": "draft", "id": "493e276e-e7f9-5930-a601-616b5d065516"}, {"name": "杜重威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朔州人，后晋将领，妻子是石敬瑭的妹妹乐平长公主。937年以护圣都指挥使身份率军驻卫州。", "biography": null, "status": "draft", "id": "e5e23c10-447f-5238-bc56-f376300f9bac"}, {"name": "萧处钧", "aliases": ["蕭處鈞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋供奉官。945年三月乙巳诸军会定州时受命暂知祁州事。生卒年本段未载。", "biography": null, "status": "draft", "id": "3bc4d3c3-a4ad-58c5-9fc7-ec173d322d4d"}, {"name": "晋廷谦", "aliases": ["晉廷謙", "晋庭谦", "晉庭謙"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹控制下的泰州刺史。945年三月庚戌向后晋军举州投降。旧五代史同次降城写晋庭谦，对应同州同日事件，保留姓名异文。生卒年本段未载。", "biography": null, "status": "draft", "id": "297483df-b9a3-558d-9fca-213403212b14"}, {"name": "没剌", "aliases": ["沒剌"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "945年后晋攻取满城时被俘的契丹首领。主书称酋长，旧本纪称相公。生卒年与是否还存在其他姓名写法本段未载，不因音近合并其他契丹首领。", "biography": null, "status": "draft", "id": "12261d26-d5c9-54d2-905c-95a8cb3f6583"}, {"name": "耶律德光", "aliases": ["德光"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：耶律德光，守西楼、受号者。", "biography": null, "status": "draft", "id": "64c415ac-57fe-571c-8c6f-3ed68fb726da"}, {"name": "李守贞", "aliases": ["李守貞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋内客省使。940年五月受命担任马全节讨伐李金全军队的都监，职务由《旧五代史》本纪补充。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "a3d16959-684f-5c82-b848-8dcbdc73e85a"}, {"name": "张彦泽", "aliases": ["張彥澤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，938年任镇国军节度使，在华州截击并杀死东行的凤翔叛军。生卒年本段未载。", "biography": null, "status": "draft", "id": "194d0f9a-3b17-5635-9741-dffc983ee32e"}, {"name": "药元福", "aliases": ["藥元福"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "并州晋阳人，早年侍奉王檀及后唐，曾任深州刺史。945年任后晋马军右厢副排阵使，在白团卫村被围时主张逆风急击，与符彦卿、张彦泽、皇甫遇领骑兵出战。《宋史》还记他战后任威州刺史。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "9bbd6971-3005-5379-8428-512e90ae87d6"}, {"name": "符彦卿", "aliases": ["符彥卿", "李彦卿", "李彥卿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：符彦卿，散员都指挥使、力战者。", "biography": null, "status": "draft", "id": "c837916f-0fdf-5954-a190-597b08cd9402"}, {"name": "皇甫遇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：皇甫遇，原严卫步军都指挥使、接侍卫步军者。", "biography": null, "status": "draft", "id": "0aa52fa6-cacc-5960-8646-9ab3a0393623"}, {"name": "赵延寿", "aliases": ["趙延壽", "延寿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：赵延寿，公主丈夫。", "biography": null, "status": "draft", "id": "bf502cd0-4cbb-52e5-b93a-e30caa907a58"}, {"name": "石重贵", "aliases": ["石重貴"], "era": "五代十国", "birth_year": 914, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：石重贵，被叙侄子及养子身份者。", "biography": null, "status": "draft", "id": "2741e60a-9bf9-56a7-b30d-3db439caa139"}, {"name": "刘知远", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘知远。", "biography": null, "status": "draft", "id": "69fa3b4b-2f0d-5799-bbf5-e378af9816e1"}, {"name": "赵在礼", "aliases": ["趙在禮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：赵在礼。", "biography": null, "status": "draft", "id": "90ff68a5-70f2-5182-8802-93859bae2990"}, {"name": "高行周", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化三年条所见人物：高行周。", "biography": null, "status": "draft", "id": "659c5f83-09bc-5282-8f02-4c7fa0a62729"}, {"name": "马全节", "aliases": ["馬全節"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：马全节，金州防御使、以私财给军并拒战者。", "biography": null, "status": "draft", "id": "bb5608d9-eabe-58ce-8c56-b07e57faadb5"}, {"name": "安审琦", "aliases": ["安審琦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：安审琦，彰圣都指挥使、领顺化节度使者。", "biography": null, "status": "draft", "id": "a579a6a1-65a5-5c8a-9c6c-be178cb049aa"}]'::jsonb)
